      <div class="primary-actions"><el-tooltip content="班次模板"><el-button :icon="Setting" circle @click="openTemplateManager"/></el-tooltip><el-button type="primary" :icon="Plus" @click="openCreate">新增班次</el-button></div>
    </header>
    <div class="roster-filters">
      <div class="filter-left"><el-segmented v-model="matrixMode" :options="matrixModeOptions" size="small"/><el-segmented v-if="myRooms.length" v-model="roomScope" :options="roomScopeOptions" size="small" @change="applyRoomScope"/><el-select v-if="matrixMode==='anchor'" v-model="filterRoomId" clearable filterable placeholder="全部直播间" class="room-filter" @change="rememberRoom"><el-option v-for="item in roomOptions" :key="item.roomId" :label="item.roomName" :value="item.roomId"><span>{{ item.roomName }}</span><small v-if="isRecentRoom(item.roomId)" class="recent-room">常用</small></el-option></el-select><el-input v-model="keyword" :prefix-icon="Search" clearable :placeholder="matrixMode==='anchor'?'搜索人员':'搜索直播间'" class="roster-search"/></div>
