    </div>
    <section class="matrix-shell">
      <div class="matrix-legend"><span><i class="legend-dot pending"></i>已排班</span><span><i class="legend-dot live"></i>进行中</span><span><i class="legend-dot waiting"></i>待上报</span><span><i class="legend-dot done"></i>已上报</span></div>
      <div class="roster-matrix" :style="matrixGridStyle">
