            <button v-for="shift in matrixCellShifts(entity,day.date)" :key="shift.shiftId" type="button" class="matrix-shift" :class="[`status-${displayStatus(shift).code.toLowerCase()}`,{reported:shift.submissionId,'single-line':matrixMode==='anchor'&&entity.roomCount<=1&&!shift.submissionId}]" :style="shiftAccent(shift)" :title="matrixShiftTitle(shift)" @click.stop="edit(shift)">
              <strong>{{ timeOnly(shift.startTime) }}–{{ timeOnly(shift.endTime) }}</strong><span v-if="matrixMode==='room'||entity.roomCount>1">{{ matrixMode==='anchor'?shift.roomName:(shift.anchorName||'未安排主播') }}</span><span v-if="shift.submissionId" class="shift-report">曝 {{ metricValue(shift.exposureDelta) }} · 看 {{ metricValue(shift.watchDelta) }}</span><span v-if="shift.submissionId" class="shift-report">互 {{ metricValue(shift.interactionDelta) }} · 粉 {{ metricValue(shift.newFanDelta) }} · 成 {{ metricValue(shift.dealDelta) }}</span>
            </button>
            <el-icon v-if="!matrixCellShifts(entity,day.date).length" class="cell-add"><Plus /></el-icon>
          </div>
        </template>
      </div>
      <div v-if="!matrixRows.length" class="matrix-empty"><el-icon><Calendar /></el-icon><span>当前范围没有可排班的人员或直播间</span></div>
    </section>
    <el-drawer v-model="visible" :title="form.shiftId ? '编辑班次' : '快速排班'" size="min(560px, 100%)" destroy-on-close>
      <div v-if="myRooms.length" class="drawer-scope-row"><el-segmented v-model="roomScope" :options="roomScopeOptions" size="small" @change="applyRoomScope"/></div>
      <el-form ref="formRef" :model="form" :rules="rules" label-position="top">
        <div class="form-grid"><el-form-item label="直播间" prop="roomId"><el-select v-model="form.roomId" filterable placeholder="选择直播间" style="width:100%" @change="handleRoomChange"><el-option v-for="item in roomOptions" :key="item.roomId" :label="item.roomName" :value="item.roomId"><span>{{ item.roomName }}</span><small v-if="isRecentRoom(item.roomId)" class="recent-room">常用</small></el-option></el-select></el-form-item><el-form-item label="排班主播" prop="anchorUserId"><el-select v-model="form.anchorUserId" filterable :disabled="!form.roomId||!roomAnchors.length" :placeholder="anchorPlaceholder" style="width:100%"><el-option v-for="item in roomAnchors" :key="item.userId" :label="anchorOptionLabel(item)" :value="item.userId"/></el-select></el-form-item></div>
        <el-form-item label="排班日期" required><div class="date-template-line"><el-date-picker v-model="form.shiftDate" type="date" value-format="YYYY-MM-DD" format="YYYY年M月D日" :clearable="false"/><el-button v-if="form.roomId" text type="primary" :icon="Setting" @click="openTemplateManager">管理模板</el-button></div></el-form-item>
        <el-form-item :label="form.shiftId ? '班次时间' : '班次安排'" required>
          <div v-if="form.roomId && shiftTemplates.length" class="quick-times compact-templates"><button v-for="item in shiftTemplates" :key="item.templateId" type="button" :class="{active:form.shiftId && (form.startClock===item.startClock&&form.endClock===item.endClock)}" @click="form.shiftId ? applyTemplate(item) : addCreateTemplateSlot(item)">{{ item.templateName }} <small>{{ item.startClock }}–{{ item.endClock }}</small></button></div>
          <template v-if="form.shiftId"><div class="time-range"><el-time-select v-model="form.startClock" start="00:00" step="00:30" end="23:30" placeholder="开始时刻"/><span>至</span><el-time-select v-model="form.endClock" start="00:30" step="00:30" end="24:00" placeholder="结束时刻"/></div><div v-if="isOvernight" class="form-tip">结束时间在次日</div></template>
          <div v-else class="create-slots">
            <div v-for="(slot,index) in createPreview" :key="slot.slotKey" class="create-slot" :class="{invalid:slot.conflict}">
              <span class="slot-number">{{ index + 1 }}</span>
              <div class="slot-content"><div class="time-range"><el-time-select v-model="createSlots[index].startClock" start="00:00" step="00:30" end="23:30" placeholder="开始"/><span>至</span><el-time-select v-model="createSlots[index].endClock" start="00:30" step="00:30" end="24:00" placeholder="结束"/></div><small v-if="slot.conflict||slot.overnight" :class="slot.conflict?'conflict-text':'ready-text'">{{ slot.conflict || '次日结束' }}</small></div>
              <el-tooltip :content="createSlots.length===1?'至少保留一场':'移除这一场'"><el-button :icon="Delete" circle text type="danger" :disabled="createSlots.length===1" @click="removeCreateSlot(slot.slotKey)"/></el-tooltip>
            </div>
            <el-button class="add-create-slot" :icon="Plus" plain :disabled="createSlots.length>=4" @click="addCreateSlot">继续添加下一场</el-button>
          </div>
        </el-form-item>
        <el-form-item label="备注"><el-input v-model="form.remark" maxlength="500" clearable placeholder="选填"/></el-form-item>
      </el-form>
      <template #footer><div class="drawer-footer"><el-button v-if="form.shiftId&&!editingShift?.submissionId" type="danger" plain :icon="Delete" :loading="deleting" @click="removeShift">删除班次</el-button><span v-else-if="form.shiftId" class="save-summary">已有上报记录，班次需保留</span><span v-else class="save-summary"><template v-if="createBlockedCount"><span>{{ createBlockedCount }} 场需调整，修正后可一次保存</span></template><template v-else>{{ createReadyCount }} 场已就绪</template></span><div><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!form.shiftId&&(!createReadyCount||createBlockedCount>0)" @click="submit">{{ form.shiftId ? '保存修改' : `保存 ${createSlots.length} 场` }}</el-button></div></div></template>
    </el-drawer>
    <el-drawer v-model="templateVisible" title="班次模板" size="520px" destroy-on-close>
      <div class="manager-toolbar"><el-select v-model="managerRoomId" filterable placeholder="选择直播间" @change="handleManagerRoomChange"><el-option v-for="item in roomOptions" :key="item.roomId" :label="item.roomName" :value="item.roomId"><span>{{ item.roomName }}</span><small v-if="isRecentRoom(item.roomId)" class="recent-room">常用</small></el-option></el-select><el-button type="primary" :icon="Plus" :disabled="!managerRoomId" @click="editManagedTemplate()">新建模板</el-button></div>
      <div v-if="managerTemplates.length" class="manager-list"><div v-for="item in managerTemplates" :key="item.templateId" class="manager-item"><div><strong>{{ item.templateName }}</strong><span>{{ item.startClock }} 至 {{ item.endClock }}</span></div><div><el-button text :icon="Edit" @click="editManagedTemplate(item)">修改</el-button><el-button text type="danger" :icon="Delete" @click="removeManagedTemplate(item)">删除</el-button></div></div></div>
      <el-empty v-else :description="managerRoomId?'该直播间还没有模板':'请先选择直播间'" :image-size="80"/>
      <div v-if="templateEditing" class="manager-editor"><h4>{{ managedForm.templateId?'修改模板':'新建模板' }}</h4><el-form label-position="top"><el-form-item label="模板名称"><el-input v-model.trim="managedForm.templateName" maxlength="50" placeholder="例如：上午班"/></el-form-item><el-form-item label="班次时间"><div class="time-range"><el-time-select v-model="managedForm.startClock" start="00:00" step="00:30" end="23:30" placeholder="开始时刻"/><span>至</span><el-time-select v-model="managedForm.endClock" start="00:30" step="00:30" end="24:00" placeholder="结束时刻"/></div></el-form-item></el-form><div class="editor-actions"><el-button @click="templateEditing=false">取消</el-button><el-button type="primary" :loading="templateSaving" @click="submitManagedTemplate">保存模板</el-button></div></div>
    </el-drawer>
    <el-drawer v-model="staffVisibilityVisible" title="人员显示" size="min(460px, 100%)" destroy-on-close>
      <div class="staff-visibility-toolbar"><el-input v-model="staffVisibilityKeyword" :prefix-icon="Search" clearable placeholder="搜索人员"/><el-button text type="primary" @click="showAllStaff">全部显示</el-button></div>
      <el-checkbox-group v-model="draftVisibleUserIds" class="staff-visibility-list">
        <el-checkbox v-for="item in filteredVisibilityStaff" :key="item.userId" :value="Number(item.userId)" :disabled="Number(item.userId)===Number(currentUserId)"><span class="visibility-person"><strong>{{ item.userName }}</strong><small>{{ staffRoomNames(item.userId) }}</small></span></el-checkbox>
      </el-checkbox-group>
      <el-empty v-if="!filteredVisibilityStaff.length" description="没有匹配的人员" :image-size="72"/>
      <template #footer><div class="drawer-footer"><span class="save-summary">未勾选的人员只对当前账号隐藏</span><div><el-button @click="staffVisibilityVisible=false">取消</el-button><el-button type="primary" :loading="staffVisibilitySaving" @click="saveStaffVisibility">保存</el-button></div></div></template>
    </el-drawer>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { ArrowLeft, ArrowRight, Calendar, Delete, Edit, Plus, Refresh, Search, Setting, User } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { deleteMetricShift, deleteShiftTemplate, getMetricOptions, listMetricShifts, listShiftTemplates, saveMetricShift, saveMetricShiftWeek, saveMetricStaffVisibility, saveShiftTemplate } from '@/api/liveMetrics'
const pad=v=>String(v).padStart(2,'0'), localDate=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`, today=()=>localDate(new Date())
const currentDate=ref(today()),rangeDate=ref(today()),keyword=ref(''),filterRoomId=ref(null),roomScope=ref('mine'),matrixMode=ref('anchor'),shifts=ref([]),rooms=ref([]),myRooms=ref([]),allRooms=ref([]),staff=ref([]),currentUserId=ref(null),showAllRooms=ref(false),shiftTemplates=ref([]),activeTemplateId=ref(null),visible=ref(false),saving=ref(false),deleting=ref(false),formRef=ref(),templateVisible=ref(false),managerRoomId=ref(null),managerTemplates=ref([]),templateEditing=ref(false),templateSaving=ref(false)
const hiddenUserIds=ref([]),staffVisibilityVisible=ref(false),staffVisibilityKeyword=ref(''),draftVisibleUserIds=ref([]),staffVisibilitySaving=ref(false)
const LAST_ROOM_KEY='live-metrics-last-room'
const RECENT_ROOMS_KEY='live-metrics-recent-rooms'
function loadRecentRooms(){try{const value=JSON.parse(localStorage.getItem(RECENT_ROOMS_KEY)||'[]');return Array.isArray(value)?value.map(Number).filter(Boolean):[]}catch{return[]}}
const recentRoomIds=ref(loadRecentRooms())
const roomScopeOptions=computed(()=>[{label:'我的直播间',value:'mine',disabled:!myRooms.value.length},{label:'全部直播间',value:'all'}])
const roomOptions=computed(()=>{const recent=new Map(recentRoomIds.value.map((id,index)=>[Number(id),index])),mine=new Set(myRooms.value.map(item=>Number(item.roomId)));return[...rooms.value].sort((a,b)=>{const ar=recent.has(Number(a.roomId))?recent.get(Number(a.roomId)):99,br=recent.has(Number(b.roomId))?recent.get(Number(b.roomId)):99;if(ar!==br)return ar-br;const am=mine.has(Number(a.roomId))?0:1,bm=mine.has(Number(b.roomId))?0:1;return am-bm||String(a.roomName||'').localeCompare(String(b.roomName||''),'zh-CN')})})
const matrixModeOptions=[{label:'按人员',value:'anchor'},{label:'按直播间',value:'room'}]
const form=reactive({shiftId:null,roomId:null,anchorUserId:null,shiftDate:'',startClock:'09:00',endClock:'12:00',remark:''})
let weekSlotSequence=0
const createWeekSlot=(startClock='09:00',endClock='12:00',templateId=null)=>({slotKey:++weekSlotSequence,templateId,startClock,endClock})
const createSlots=ref([createWeekSlot()])
const managedForm=reactive({templateId:null,templateName:'',startClock:'09:00',endClock:'12:00'})
const rules={roomId:[{required:true,message:'请选择直播间',trigger:'change'}],anchorUserId:[{required:true,message:'请选择主播',trigger:'change'}]}
const selectedRoom=computed(()=>rooms.value.find(x=>Number(x.roomId)===Number(form.roomId)))
const editingShift=computed(()=>shifts.value.find(item=>Number(item.shiftId)===Number(form.shiftId)))
const roomAnchors=computed(()=>{const editingId=Number(form.anchorUserId);return allAnchorsForRoom(selectedRoom.value).filter(item=>isStaffVisible(item.userId)||Number(item.userId)===editingId)})
const anchorPlaceholder=computed(()=>!form.roomId?'请先选择直播间':roomAnchors.value.length?'请选择主播':'该直播间还没有配置主播')
const isOvernight=computed(()=>form.startClock&&form.endClock&&form.endClock!=='24:00'&&form.endClock<=form.startClock)
const visibleWeekRows=computed(()=>{const k=keyword.value.trim().toLowerCase(),allowed=new Set(rooms.value.map(x=>Number(x.roomId)));return shifts.value.filter(row=>allowed.has(Number(row.roomId))&&(!filterRoomId.value||Number(row.roomId)===Number(filterRoomId.value))&&(!k||`${row.roomName||''} ${row.anchorName||''}`.toLowerCase().includes(k))).sort((a,b)=>String(a.startTime).localeCompare(String(b.startTime)))})
const weekShiftCount=computed(()=>visibleWeekRows.value.length)
const displayDays=computed(()=>Array.from({length:9},(_,index)=>{const date=addDays(rangeDate.value,index-2),d=new Date(`${date}T12:00:00`),weekday=d.getDay();return{date,day:`${d.getMonth()+1}/${d.getDate()}`,weekday:`周${'日一二三四五六'[weekday]}`,weekend:weekday===0||weekday===6}}))
const dateWindowLabel=computed(()=>`${friendlyDate(displayDays.value[0]?.date)} - ${friendlyDate(displayDays.value.at(-1)?.date)}`)
const visibilityStaff=computed(()=>{const ids=new Set(allRooms.value.flatMap(room=>String(room.anchorIds||'').split(',').map(Number).filter(Boolean)));return staff.value.filter(item=>ids.has(Number(item.userId)))})
const filteredVisibilityStaff=computed(()=>{const k=staffVisibilityKeyword.value.trim().toLowerCase();return visibilityStaff.value.filter(item=>!k||String(item.userName||'').toLowerCase().includes(k))})
const unfilteredMatrixRows=computed(()=>{const k=keyword.value.trim().toLowerCase(),rows=visibleWeekRows.value,scopedRooms=filterRoomId.value?rooms.value.filter(room=>Number(room.roomId)===Number(filterRoomId.value)):rooms.value;if(matrixMode.value==='room')return scopedRooms.filter(room=>!k||String(room.roomName||'').toLowerCase().includes(k)).map(room=>({key:`room-${room.roomId}`,id:Number(room.roomId),name:room.roomName||'未命名直播间',subtitle:`${rows.filter(row=>Number(row.roomId)===Number(room.roomId)).length} 个班次`,type:'room'}));const roomNamesByAnchor=new Map();scopedRooms.forEach(room=>{anchorsForRoom(room).forEach(anchor=>{const id=Number(anchor.userId);if(!roomNamesByAnchor.has(id))roomNamesByAnchor.set(id,new Set());roomNamesByAnchor.get(id).add(room.roomName||'未命名直播间')})});const map=new Map(staff.value.filter(person=>isStaffVisible(person.userId)&&roomNamesByAnchor.has(Number(person.userId))).map(person=>{const id=Number(person.userId);return[id,{key:`anchor-${id}`,id,name:person.userName||person.nickName||'未命名人员',rooms:new Set(roomNamesByAnchor.get(id)),count:0,type:'anchor'}]}));rows.forEach(row=>{const id=Number(row.anchorUserId);if(!id||!isStaffVisible(id))return;const name=row.anchorName||'未命名人员';if(!map.has(id))map.set(id,{key:`anchor-${id}`,id,name,rooms:new Set(),count:0,type:'anchor'});const item=map.get(id);item.count++;if(row.roomName)item.rooms.add(row.roomName)});return[...map.values()].filter(item=>!k||`${item.name} ${[...item.rooms].join(' ')}`.toLowerCase().includes(k)).map(item=>{const roomNames=[...item.rooms],roomCount=roomNames.length,roomName=roomCount===1?roomNames[0]:'';return{...item,roomCount,roomName,subtitle:roomCount===1?roomName:roomCount>1?`${item.count} 个班次 · ${roomCount} 个直播间`:item.count?`${item.count} 个班次`:''}})})
const matrixRows=computed(()=>unfilteredMatrixRows.value)
const matrixGridStyle=computed(()=>({'--matrix-days':displayDays.value.length,gridTemplateColumns:`148px repeat(${displayDays.value.length}, minmax(110px, 1fr))`}))
const isTodayWindow=computed(()=>rangeDate.value===today())
const createPreview=computed(()=>{const candidates=createSlots.value.map((slot,index)=>({...slot,index,...buildRange(form.shiftDate,slot.startClock,slot.endClock)})),existing=shifts.value.filter(row=>Number(row.anchorUserId)===Number(form.anchorUserId)&&String(row.liveDate||row.startTime).slice(0,10)===form.shiftDate&&row.status!=='CANCELLED').length;let validBefore=0;return candidates.map(item=>{let conflict=findCreateConflict(item,candidates);if(!conflict&&existing+validBefore>=4)conflict='该主播当天最多 4 场';if(!conflict)validBefore++;return{...item,conflict}})})
const createReadyCount=computed(()=>createPreview.value.filter(item=>!item.conflict).length)
const createBlockedCount=computed(()=>createPreview.value.length-createReadyCount.value)
function timeOnly(v){return String(v||'').slice(11,16)||'--:--'}
function metricValue(v){return v===null||v===undefined?'--':Number(v).toLocaleString('zh-CN')}
function isRecentRoom(roomId){return recentRoomIds.value.includes(Number(roomId))}
function rememberRoom(roomId){const id=Number(roomId);if(!id)return;recentRoomIds.value=[id,...recentRoomIds.value.filter(item=>item!==id)].slice(0,5);localStorage.setItem(RECENT_ROOMS_KEY,JSON.stringify(recentRoomIds.value));localStorage.setItem(LAST_ROOM_KEY,String(id))}
function addDays(value,amount){const d=new Date(`${value}T12:00:00`);d.setDate(d.getDate()+amount);return localDate(d)}
function shortMoment(v){const text=String(v||'');return text?`${text.slice(5,10).replace('-','/')} ${text.slice(11,16)}`:'--'}
function fullShiftTime(start,end){return `${shortMoment(start)} - ${shortMoment(end)}`}
function formatSubmittedAt(v){const text=String(v||'');return text?`上报 ${text.slice(5,16).replace('-','/')}`:'暂无上报时间'}
function displayStatus(row){if(row.status==='CANCELLED')return{code:'CANCELLED',label:'已取消',type:'info'};if(row.submissionId)return{code:'REPORTED',label:'已上报',type:'success'};const n=Date.now(),s=new Date(String(row.startTime).replace(' ','T')).getTime(),e=new Date(String(row.endTime).replace(' ','T')).getTime();if(n<s)return s-n<=1800000?{code:'SOON',label:'即将开始',type:'warning'}:{code:'PENDING',label:'待开始',type:'info'};if(n<=e)return{code:'LIVE',label:'进行中',type:'success'};return{code:'WAITING',label:'待上报',type:'danger'}}
async function load(){const p={beginDate:displayDays.value[0]?.date||rangeDate.value,endDate:displayDays.value.at(-1)?.date||rangeDate.value};const response=await listMetricShifts(p);shifts.value=response.data||[]}
function selectDay(date){currentDate.value=date}
function applyRoomScope(value){if(value==='mine'&&!myRooms.value.length){roomScope.value='all';showAllRooms.value=true}else showAllRooms.value=value==='all';changeRoomScope()}
async function moveDateWindow(amount){rangeDate.value=addDays(rangeDate.value,amount);currentDate.value=rangeDate.value;await load()}
async function changeDateWindow(value){if(!value)return;currentDate.value=value;await load()}
async function goTodayWindow(){rangeDate.value=today();currentDate.value=today();await load()}
function matrixCellShifts(entity,date){return visibleWeekRows.value.filter(row=>String(row.liveDate||row.startTime).slice(0,10)===date&&(entity.type==='anchor'?Number(row.anchorUserId)===entity.id:Number(row.roomId)===entity.id))}
async function openMatrixCell(entity,date){currentDate.value=date;resetForm();form.shiftDate=date;if(entity.type==='room'){form.roomId=entity.id;await handleRoomChange()}else{form.anchorUserId=entity.id;const matchingRooms=rooms.value.filter(room=>anchorsForRoom(room).some(anchor=>Number(anchor.userId)===entity.id));if(matchingRooms.length===1){form.roomId=Number(matchingRooms[0].roomId);await loadTemplates()}}visible.value=true}
function matrixShiftTitle(shift){return `${matrixMode.value==='anchor'?shift.roomName:shift.anchorName||'未安排主播'}\n${timeOnly(shift.startTime)}–${timeOnly(shift.endTime)}\n${displayStatus(shift).label}`}
function colorFor(value){const colors=['#1677ff','#00a870','#7c5ce7','#e56a16','#1685a9','#d04a68','#5c6f82','#b7791f'];let hash=0;for(const char of String(value||''))hash=(hash*31+char.charCodeAt(0))>>>0;return colors[hash%colors.length]}
function shiftAccent(shift){return{'--shift-accent':colorFor(matrixMode.value==='anchor'?shift.roomName:shift.anchorName)}}
watch(matrixMode,()=>{filterRoomId.value=null})
function friendlyDate(value){if(!value)return'';const d=new Date(`${value}T12:00:00`);return`${d.getMonth()+1}月${d.getDate()}日`}
function datePlusOne(value){const d=new Date(`${value}T12:00:00`);d.setDate(d.getDate()+1);return localDate(d)}
function allAnchorsForRoom(room){const ids=String(room?.anchorIds||'').split(',').map(Number).filter(Boolean),map=new Map(staff.value.map(x=>[Number(x.userId),x]));return ids.map(id=>map.get(id)).filter(Boolean)}
function isStaffVisible(userId){return Number(userId)===Number(currentUserId.value)||!hiddenUserIds.value.includes(Number(userId))}
function anchorsForRoom(room){return allAnchorsForRoom(room).filter(item=>isStaffVisible(item.userId))}
function staffRoomNames(userId){const names=allRooms.value.filter(room=>String(room.anchorIds||'').split(',').map(Number).includes(Number(userId))).map(room=>room.roomName).filter(Boolean);return names.join('、')||'未配置直播间'}
function openStaffVisibility(){staffVisibilityKeyword.value='';draftVisibleUserIds.value=visibilityStaff.value.filter(item=>isStaffVisible(item.userId)).map(item=>Number(item.userId));if(currentUserId.value&&!draftVisibleUserIds.value.includes(Number(currentUserId.value)))draftVisibleUserIds.value.push(Number(currentUserId.value));staffVisibilityVisible.value=true}
function showAllStaff(){draftVisibleUserIds.value=visibilityStaff.value.map(item=>Number(item.userId))}
async function saveStaffVisibility(){const visible=new Set(draftVisibleUserIds.value.map(Number)),hidden=visibilityStaff.value.map(item=>Number(item.userId)).filter(id=>id!==Number(currentUserId.value)&&!visible.has(id));staffVisibilitySaving.value=true;try{await saveMetricStaffVisibility({hiddenUserIds:hidden});hiddenUserIds.value=hidden;staffVisibilityVisible.value=false;ElMessage.success('人员显示已保存')}finally{staffVisibilitySaving.value=false}}
function anchorOptionLabel(item){return `${item.userName}${Number(item.userId)===Number(currentUserId.value)?'（我）':''}`}
async function loadTemplates(){activeTemplateId.value=null;shiftTemplates.value=form.roomId?(await listShiftTemplates(form.roomId)).data||[]:[];if(!form.shiftId&&shiftTemplates.value.length&&createSlots.value.length===1){const first=shiftTemplates.value[0];createSlots.value=[createWeekSlot(first.startClock,first.endClock,first.templateId)]}}
async function handleRoomChange(){rememberRoom(form.roomId);const ids=roomAnchors.value.map(x=>Number(x.userId)),preferred=roomAnchors.value.find(x=>Number(x.userId)===Number(currentUserId.value));if(!ids.includes(Number(form.anchorUserId)))form.anchorUserId=preferred?.userId||(ids.length===1?ids[0]:null);await loadTemplates()}
function applyTemplate(item){activeTemplateId.value=item.templateId;form.startClock=item.startClock;form.endClock=item.endClock}
function addCreateTemplateSlot(item){const exists=createSlots.value.some(slot=>slot.startClock===item.startClock&&slot.endClock===item.endClock);if(exists)return ElMessage.info('这一场已经在排班列表中');if(createSlots.value.length>=4)return ElMessage.warning('同一天最多安排 4 场');const first=createSlots.value[0];if(createSlots.value.length===1&&!first.templateId&&first.startClock==='09:00'&&first.endClock==='12:00')createSlots.value=[createWeekSlot(item.startClock,item.endClock,item.templateId)];else createSlots.value.push(createWeekSlot(item.startClock,item.endClock,item.templateId))}
async function loadManagerTemplates(){templateEditing.value=false;managerTemplates.value=managerRoomId.value?(await listShiftTemplates(managerRoomId.value)).data||[]:[]}
async function handleManagerRoomChange(){rememberRoom(managerRoomId.value);await loadManagerTemplates()}
async function openTemplateManager(){managerRoomId.value=form.roomId||managerRoomId.value||rooms.value[0]?.roomId||null;templateVisible.value=true;await loadManagerTemplates()}
function editManagedTemplate(item){Object.assign(managedForm,item?{templateId:item.templateId,templateName:item.templateName,startClock:item.startClock,endClock:item.endClock}:{templateId:null,templateName:'',startClock:'09:00',endClock:'12:00'});templateEditing.value=true}
async function submitManagedTemplate(){if(!managedForm.templateName)return ElMessage.warning('请输入模板名称');if(!managedForm.startClock||!managedForm.endClock)return ElMessage.warning('请选择完整班次时间');templateSaving.value=true;try{await saveShiftTemplate({...managedForm,roomId:managerRoomId.value});ElMessage.success(managedForm.templateId?'模板已修改':'模板已新建');templateEditing.value=false;await loadManagerTemplates();if(Number(form.roomId)===Number(managerRoomId.value))await loadTemplates()}finally{templateSaving.value=false}}
async function removeManagedTemplate(item){await ElMessageBox.confirm(`确定删除“${item.templateName}”吗？`,'删除模板',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await deleteShiftTemplate(item.templateId);ElMessage.success('模板已删除');await loadManagerTemplates();if(Number(form.roomId)===Number(managerRoomId.value))await loadTemplates()}
function resetForm(){const remembered=Number(localStorage.getItem(LAST_ROOM_KEY)),roomId=rooms.value.some(item=>Number(item.roomId)===remembered)?remembered:(rooms.value.length===1?Number(rooms.value[0].roomId):null);Object.assign(form,{shiftId:null,roomId,anchorUserId:null,shiftDate:currentDate.value,startClock:'09:00',endClock:'12:00',remark:''});createSlots.value=[createWeekSlot()]}
function splitDateTime(value){const text=String(value||'');return{date:text.slice(0,10),clock:text.slice(11,16)}}
async function openCreate(){resetForm();shiftTemplates.value=[];if(form.roomId)await handleRoomChange();visible.value=true}
async function openCreateForDate(date){currentDate.value=date;await openCreate()}
async function edit(row){const start=splitDateTime(row.startTime),end=splitDateTime(row.endTime);Object.assign(form,{shiftId:row.shiftId,roomId:row.roomId,anchorUserId:Number(row.anchorUserId),shiftDate:start.date,startClock:start.clock,endClock:end.date!==start.date&&end.clock==='00:00'?'24:00':end.clock,remark:row.remark||''});await loadTemplates();visible.value=true}
async function removeShift(){const row=shifts.value.find(item=>Number(item.shiftId)===Number(form.shiftId));const anchor=row?.anchorName||staff.value.find(item=>Number(item.userId)===Number(form.anchorUserId))?.userName||'该主播';await ElMessageBox.confirm(`确定删除 ${anchor} 在 ${friendlyDate(form.shiftDate)} ${form.startClock}–${form.endClock} 的班次吗？删除后无法恢复。`,'删除班次',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'保留班次'});deleting.value=true;try{await deleteMetricShift(form.shiftId);ElMessage.success('班次已删除');visible.value=false;await load()}finally{deleting.value=false}}
async function copyShift(row){const start=splitDateTime(row.startTime),end=splitDateTime(row.endTime),endClock=end.date!==start.date&&end.clock==='00:00'?'24:00':end.clock;Object.assign(form,{shiftId:null,roomId:row.roomId,anchorUserId:Number(row.anchorUserId),shiftDate:currentDate.value,startClock:start.clock,endClock,remark:row.remark||''});await handleRoomChange();createSlots.value=[createWeekSlot(start.clock,endClock)];visible.value=true;ElMessage.info('已复制到当前日期，确认后可以继续添加其他场次')}
async function copyShiftToDate(row,date){currentDate.value=date;await copyShift(row)}
async function submit(){await formRef.value?.validate();if(!form.shiftDate)return ElMessage.warning('请选择排班日期');if(!form.shiftId&&createBlockedCount.value)return ElMessage.warning('请先修正标红的班次，系统不会遗漏任何一场');saving.value=true;try{if(form.shiftId){if(!form.startClock||!form.endClock)return ElMessage.warning('请选择完整班次时间');const range=buildRange(form.shiftDate,form.startClock,form.endClock);await saveMetricShift({shiftId:form.shiftId,roomId:form.roomId,anchorUserId:form.anchorUserId,startTime:range.startTime,endTime:range.endTime,remark:form.remark});ElMessage.success('班次已修改')}else{const ready=createPreview.value.filter(item=>!item.conflict);if(!ready.length)return ElMessage.warning('没有可保存的班次，请先调整标红的时间');const response=await saveMetricShiftWeek({roomId:form.roomId,items:ready.map(item=>({anchorUserId:form.anchorUserId,startTime:item.startTime,endTime:item.endTime,remark:form.remark}))}),result=response.data||{};if(!result.created)return ElMessage.warning('没有生成班次，请按提示调整');if(result.skipped)ElMessage.warning(`已保存 ${result.created} 场，另有 ${result.skipped} 场发生新冲突，请重新检查`);else ElMessage.success(`已保存 ${result.created} 场`)}visible.value=false;await load()}finally{saving.value=false}}
function changeRoomScope(){if(!showAllRooms.value&&!myRooms.value.length)showAllRooms.value=true;roomScope.value=showAllRooms.value?'all':'mine';rooms.value=showAllRooms.value?allRooms.value:myRooms.value;const contains=id=>rooms.value.some(x=>Number(x.roomId)===Number(id));if(filterRoomId.value&&!contains(filterRoomId.value))filterRoomId.value=null;if(form.roomId&&!contains(form.roomId)){form.roomId=null;form.anchorUserId=null;shiftTemplates.value=[]}if(managerRoomId.value&&!contains(managerRoomId.value)){managerRoomId.value=null;managerTemplates.value=[]}}
function buildRange(date,startClock,endClock){if(!date||!startClock||!endClock)return{startTime:'',endTime:'',overnight:false};const overnight=endClock==='24:00'||endClock<=startClock,endDate=overnight?addDays(date,1):date,normalizedEnd=endClock==='24:00'?'00:00':endClock;return{startTime:`${date} ${startClock}:00`,endTime:`${endDate} ${normalizedEnd}:00`,overnight}}
function findCreateConflict(item,candidates){if(!form.roomId||!form.anchorUserId)return'请先选择直播间和主播';if(!item.startTime||!item.endTime)return'请补全开始和结束时间';const start=new Date(item.startTime.replace(' ','T')).getTime(),end=new Date(item.endTime.replace(' ','T')).getTime(),overlap=row=>{const a=new Date(String(row.startTime).replace(' ','T')).getTime(),b=new Date(String(row.endTime).replace(' ','T')).getTime();return a<end&&b>start&&row.status!=='CANCELLED'};const duplicate=candidates.find(row=>row.slotKey!==item.slotKey&&overlap(row));if(duplicate)return`与第 ${duplicate.index+1} 场时间重叠`;if(shifts.value.some(row=>Number(row.roomId)===Number(form.roomId)&&overlap(row)))return'直播间已有重叠班次';if(shifts.value.some(row=>Number(row.anchorUserId)===Number(form.anchorUserId)&&overlap(row)))return'主播同时段已有其他班次';return null}
function addCreateSlot(){if(createSlots.value.length>=4)return ElMessage.warning('同一天最多安排 4 场');const last=createSlots.value.at(-1),start=last?.endClock&&last.endClock!=='24:00'?last.endClock:'09:00';createSlots.value.push(createWeekSlot(start,addClockHours(start,3)))}
function removeCreateSlot(slotKey){if(createSlots.value.length>1)createSlots.value=createSlots.value.filter(slot=>slot.slotKey!==slotKey)}
function addClockHours(clock,hours){const [h,m]=String(clock).split(':').map(Number),total=Math.min(24*60,h*60+m+hours*60);return total===24*60?'24:00':`${pad(Math.floor(total/60))}:${pad(total%60)}`}
onMounted(async()=>{const r=await getMetricOptions();myRooms.value=r.data?.rooms||[];allRooms.value=r.data?.allRooms||myRooms.value;showAllRooms.value=!myRooms.value.length;roomScope.value=showAllRooms.value?'all':'mine';rooms.value=showAllRooms.value?allRooms.value:myRooms.value;staff.value=r.data?.staff||[];currentUserId.value=r.data?.currentUserId||null;hiddenUserIds.value=(r.data?.hiddenUserIds||[]).map(Number);await load()})
